/**
 * Base62 encoder/decoder for URL shortening
 * Character set: 0-9, a-z, A-Z (62 characters)
 */

const CHARS = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
const BASE = 62;

/**
 * Encode a number to Base62 string
 * @param {number} num - The number to encode
 * @returns {string} Base62 encoded string
 */
export function encode(num) {
  if (num === 0) return CHARS[0];
  if (num < 0) throw new Error('Cannot encode negative numbers');

  let result = '';
  while (num > 0) {
    result = CHARS[num % BASE] + result;
    num = Math.floor(num / BASE);
  }
  return result;
}

/**
 * Decode a Base62 string to number
 * @param {string} str - The Base62 string to decode
 * @returns {number} Decoded number
 */
export function decode(str) {
  if (!str || typeof str !== 'string') {
    throw new Error('Invalid input: must be a non-empty string');
  }

  return str.split('').reduce((acc, char) => {
    const index = CHARS.indexOf(char);
    if (index === -1) {
      throw new Error(`Invalid character in short code: ${char}`);
    }
    return acc * BASE + index;
  }, 0);
}

/**
 * Generate a short code with a minimum length
 * @param {number} id - The database ID
 * @param {number} minLength - Minimum length of the short code (default: 4)
 * @returns {string} Short code
 */
export function generateShortCode(id, minLength = 4) {
  let encoded = encode(id);
  // Pad with leading zeros if needed
  while (encoded.length < minLength) {
    encoded = CHARS[0] + encoded;
  }
  return encoded;
}

/**
 * Tests for Base62 encoder/decoder
 */
import { encode, decode, generateShortCode } from '../src/encoder.js';

describe('Base62 Encoder', () => {
  test('encode(0) should return "0"', () => {
    expect(encode(0)).toBe('0');
  });

  test('encode(1) should return "1"', () => {
    expect(encode(1)).toBe('1');
  });

  test('encode(10) should return "a"', () => {
    expect(encode(10)).toBe('a');
  });

  test('encode(35) should return "z"', () => {
    expect(encode(35)).toBe('z');
  });

  test('encode(36) should return "A"', () => {
    expect(encode(36)).toBe('A');
  });

  test('encode(61) should return "Z"', () => {
    expect(encode(61)).toBe('Z');
  });

  test('encode(62) should return "10"', () => {
    expect(encode(62)).toBe('10');
  });

  test('encode(12345) should return "d7C"', () => {
    expect(encode(12345)).toBe('d7C');
  });

  test('should throw for negative numbers', () => {
    expect(() => encode(-1)).toThrow('Cannot encode negative numbers');
  });
});

describe('Base62 Decoder', () => {
  test('decode("0") should return 0', () => {
    expect(decode('0')).toBe(0);
  });

  test('decode("1") should return 1', () => {
    expect(decode('1')).toBe(1);
  });

  test('decode("a") should return 10', () => {
    expect(decode('a')).toBe(10);
  });

  test('decode("Z") should return 61', () => {
    expect(decode('Z')).toBe(61);
  });

  test('decode("10") should return 62', () => {
    expect(decode('10')).toBe(62);
  });

  test('decode("d7C") should return 12345', () => {
    expect(decode('d7C')).toBe(12345);
  });

  test('should throw for invalid characters', () => {
    expect(() => decode('abc!')).toThrow('Invalid character');
  });

  test('should throw for empty string', () => {
    expect(() => decode('')).toThrow('Invalid input');
  });

  test('should throw for null', () => {
    expect(() => decode(null)).toThrow('Invalid input');
  });
});

describe('Encode/Decode Round Trip', () => {
  test('round trip for small numbers', () => {
    for (let i = 0; i < 100; i++) {
      expect(decode(encode(i))).toBe(i);
    }
  });

  test('round trip for large numbers', () => {
    const testNumbers = [1000000, 999999999, 1234567890123];
    testNumbers.forEach(num => {
      expect(decode(encode(num))).toBe(num);
    });
  });
});

describe('generateShortCode', () => {
  test('should generate code with minimum length 4', () => {
    const code = generateShortCode(1);
    expect(code.length).toBeGreaterThanOrEqual(4);
  });

  test('should pad with leading zeros', () => {
    const code = generateShortCode(1, 6);
    expect(code.length).toBe(6);
    expect(code.startsWith('00000')).toBe(true);
  });
});

