      expect(result.title).toBe('Example Site');
    });
  });

  describe('findByShortCode', () => {
    test('should find URL by short code', () => {
      insertUrl('findtest', 'https://findtest.com');
      const result = findByShortCode('findtest');
      expect(result).toBeDefined();
      expect(result.original_url).toBe('https://findtest.com');
    });

    test('should return null for non-existent code', () => {
      const result = findByShortCode('nonexistent');
      expect(result).toBeUndefined();
    });
  });

  describe('findByOriginalUrl', () => {
    test('should find URL by original URL', () => {
      insertUrl('origtest', 'https://origtest.com');
      const result = findByOriginalUrl('https://origtest.com');
      expect(result).toBeDefined();
      expect(result.short_code).toBe('origtest');
