  test('should increment click count', () => {
    const url = 'https://click-count-test.com';
    const short = shorten(url, { dbPath: testDbPath });

    expand(short.shortCode, { dbPath: testDbPath });
    const result = expand(short.shortCode, { dbPath: testDbPath });

    expect(result.clickCount).toBe(2);
  });
