describe('List Command', () => {
  let list, shorten;

  beforeAll(async () => {
    const listModule = await import('../src/commands/list.js');
    const shortenModule = await import('../src/commands/shorten.js');
    list = listModule.list;
    shorten = shortenModule.shorten;
  });

  test('should list shortened URLs', () => {
    shorten('https://list-test-1.com', { dbPath: testDbPath });
    shorten('https://list-test-2.com', { dbPath: testDbPath });

    const result = list({ dbPath: testDbPath });
    expect(result.success).toBe(true);
    expect(result.count).toBeGreaterThanOrEqual(2);
    expect(result.urls.length).toBeGreaterThanOrEqual(2);
  });

  test('should respect limit option', () => {
    const result = list({ dbPath: testDbPath, limit: 1 });
    expect(result.urls.length).toBeLessThanOrEqual(1);
  });
});

/**
 * SQLite database operations for URL shortener
 */
import Database from 'better-sqlite3';
import path from 'path';
import { homedir } from 'os';
import fs from 'fs';

let db = null;

/**
 * Get the database path
 * @param {string} customPath - Custom database path (optional)
 * @returns {string} Database file path
 */
function getDbPath(customPath) {
  if (customPath) return customPath;

  // Default to ~/.url-shortener/urls.db
  const dbDir = path.join(homedir(), '.url-shortener');
  return path.join(dbDir, 'urls.db');
}

/**
 * Initialize the database
 * @param {string} customPath - Custom database path (optional)
 * @returns {Database} Database instance
 */
export function initDb(customPath = null) {
  if (db) return db;

  const dbPath = getDbPath(customPath);
  const dbDir = path.dirname(dbPath);

  // Ensure directory exists
  if (!fs.existsSync(dbDir)) {
    fs.mkdirSync(dbDir, { recursive: true });
  }

  db = new Database(dbPath);

  // Create tables
  db.exec(`
    CREATE TABLE IF NOT EXISTS urls (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      short_code TEXT UNIQUE NOT NULL,
      original_url TEXT NOT NULL,
      title TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      expires_at DATETIME,
      click_count INTEGER DEFAULT 0
    );

    CREATE INDEX IF NOT EXISTS idx_short_code ON urls(short_code);
    CREATE INDEX IF NOT EXISTS idx_created_at ON urls(created_at);
  `);

  return db;
}

/**
 * Get database instance
 * @returns {Database} Database instance
 */
export function getDb() {
  if (!db) {
    throw new Error('Database not initialized. Call initDb() first.');
  }
  return db;
}

/**
 * Close database connection
 */
export function closeDb() {
  if (db) {
    db.close();
    db = null;
  }
}

/**
 * Insert a new URL mapping
 * @param {string} shortCode - Short code
 * @param {string} originalUrl - Original URL
 * @param {string} title - Optional title
 * @returns {object} Inserted row
 */
export function insertUrl(shortCode, originalUrl, title = null) {
  const db = getDb();
  const stmt = db.prepare(`
    INSERT INTO urls (short_code, original_url, title)
    VALUES (?, ?, ?)
  `);
  const result = stmt.run(shortCode, originalUrl, title);
