 */
import { initDb, insertUrl, findByOriginalUrl, getNextId } from '../db.js';
import { generateShortCode } from '../encoder.js';
import chalk from 'chalk';

/**
 * Validate URL format
 * @param {string} url - URL to validate
 * @returns {boolean} True if valid
 */
function isValidUrl(url) {
  try {
    new URL(url);
    return true;
  } catch {
    return false;
  }
}

/**
 * Shorten a URL
 * @param {string} url - URL to shorten
 * @param {object} options - Command options
 * @returns {object} Result object
 */
export function shorten(url, options = {}) {
  // Validate URL
  if (!isValidUrl(url)) {
    return {
      success: false,
      error: 'Invalid URL format. Please provide a valid URL (e.g., https://example.com)'
    };
  }

  // Initialize database
  initDb(options.dbPath);

  // Check if URL already exists
  const existing = findByOriginalUrl(url);
  if (existing && !options.force) {
    return {
      success: true,
      shortCode: existing.short_code,
      originalUrl: existing.original_url,
      createdAt: existing.created_at,
      clickCount: existing.click_count,
      isExisting: true
    };
  }

  // Generate short code
  const nextId = getNextId();
  const shortCode = options.customCode || generateShortCode(nextId);

  // Insert into database
  const result = insertUrl(shortCode, url, options.title);

  return {
    success: true,
    shortCode: result.short_code,
    originalUrl: result.original_url,
    id: result.id,
    isNew: true
  };
}

/**
 * Format output for display
 * @param {object} result - Result from shorten()
 * @param {object} options - Display options
 */
export function formatOutput(result, options = {}) {
  if (options.json) {
    console.log(JSON.stringify(result, null, 2));
    return;
  }

  if (!result.success) {
    console.error(chalk.red.bold('✗ Error:'), result.error);
    return;
  }

  if (result.isExisting) {
    console.log(chalk.yellow('⚠ URL already shortened:'));
    console.log(chalk.dim('  Original:'), result.originalUrl);
    console.log(chalk.dim('  Short:'), chalk.green(result.shortCode));
    console.log(chalk.dim('  Clicks:'), result.clickCount);
  } else {
    console.log(chalk.green.bold('✓ URL shortened successfully!'));
    console.log(chalk.dim('  Original:'), result.originalUrl);
    console.log(chalk.dim('  Short:'), chalk.green.bold(result.shortCode));
    console.log(chalk.dim('  ID:'), result.id);
  }
}

